"use client";

import { useState } from "react";

import { FileStackIcon } from "@/components/icons";
import { AppShell } from "@/components/shared/AppShell";
import { UploadBox } from "@/components/upload/UploadBox";
import { DocumentCard } from "@/components/upload/DocumentCard";
import { ProgressBar } from "@/components/ui/ProgressBar";
import { EmptyState } from "@/components/ui/EmptyState";
import { Card } from "@/components/ui/Card";

import { useDocuments } from "@/hooks/useDocuments";
import { uploadDocument } from "@/services/api";
import { useToast } from "@/components/ui/Toast";

export default function UploadPage() {
  const { documents, addDocument, remove } = useDocuments();
  const toast = useToast();

  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [fileName, setFileName] = useState("");

  async function handleFiles(files: File[]) {
    if (!files.length) return;

    const file = files[0];

    setUploading(true);
    setFileName(file.name);

    try {
      const document = await uploadDocument(file, setProgress);

      addDocument(document);
      toast.success("Document uploaded successfully");
    } catch (err) {
      console.error(err);
      toast.error("Upload failed");
    } finally {
      setUploading(false);
      setProgress(0);
      setFileName("");
    }
  }

  return (
    <AppShell title="Upload">
      <UploadBox onFilesSelected={handleFiles} />

      {uploading && (
        <Card hoverLift={false}>
          <p className="truncate">{fileName}</p>
          <ProgressBar value={progress} />
        </Card>
      )}

      <h2 className="section-title">
        Uploaded Documents ({documents.length})
      </h2>

      {documents.length === 0 ? (
        <EmptyState
          icon={<FileStackIcon size={24} />}
          title="No uploaded documents"
          description="Upload a document to begin."
        />
      ) : (
        <div className="grid-docs">
          {documents.map((doc) => (
            <DocumentCard
              key={doc.id}
              document={doc}
              onDelete={remove}
            />
          ))}
        </div>
      )}
    </AppShell>
  );
}